files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #17120b;
  --vt-ink: #1b1917;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;
  --vt-on-accent: #241b0f;
  --vt-accent-ink: #c12828;
  --vt-accent-on-deep: #f4b942;
  --vt-line: #e2dccf;
  font-family: 'Manrope', system-ui, -apple-system, sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  line-height: 1.6;
  min-height: 100vh;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(button) {
  font: inherit;
  color: inherit;
  background: none;
  border: none;
}

.root :where(img) {
  display: block;
  max-width: 100%;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  margin: 0;
  font-weight: 700;
  color: var(--vt-ink);
  line-height: 1.15;
}

.root a:focus-visible,
.root button:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 3px;
}

.root .sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: 300px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 44px;
  padding: 40px 28px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  z-index: 100;
}

.root .logo {
  display: inline-flex;
  align-items: center;
}

.root .logoBrand {
  width: 150px;
  height: auto;
}

.root .navLinks {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
}

.root .navLinks a {
  position: relative;
  padding: 4px 2px;
  color: var(--vt-on-accent);
  font-size: 0.95rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: color 0.3s;
}

.root .navLinks a::after {
  content: '';
  position: absolute;
  left: 50%;
  right: 50%;
  bottom: 0;
  height: 2px;
  background: var(--vt-on-accent);
  transition: left 0.3s ease, right 0.3s ease;
}

.root .navLinks a:hover {
  color: var(--vt-on-deep);
}

.root .navLinks a:hover::after {
  left: 0;
  right: 0;
}

.root .main {
  margin-left: 300px;
  min-height: 100vh;
}

.root .hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: 110px 64px;
  background-size: cover;
  background-position: center;
  background-color: var(--vt-surface-deep);
  overflow: hidden;
  border-bottom: 12px solid var(--vt-accent);
  color: var(--vt-on-deep);
}

.root .heroOverlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, var(--vt-accent-ink), var(--vt-accent));
  opacity: 0.72;
  pointer-events: none;
}

.root .heroContent {
  position: relative;
  z-index: 1;
  max-width: 700px;
}

.root .heroKicker {
  margin-bottom: 16px;
  color: var(--vt-on-deep);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.root .heroTitle {
  color: var(--vt-on-deep);
  font-size: clamp(2.8rem, 6vw, 4.8rem);
}

.root .heroTitle strong {
  color: var(--vt-on-deep);
}

.root .heroTitle em {
  color: var(--vt-accent-on-deep);
  font-style: italic;
}

.root .heroTagline {
  margin: 20px 0 32px;
  max-width: 54ch;
  color: var(--vt-on-deep);
  opacity: 0.92;
  font-size: 1.1rem;
}

.root .heroButtons {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.root .btnPrimary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 26px;
  border-radius: 999px;
  background: var(--vt-accent-ink);
  border: 2px solid transparent;
  color: var(--vt-on-deep);
  font-weight: 700;
  font-size: 0.95rem;
  transition: background 0.3s ease, transform 0.3s ease;
}

.root .btnPrimary:hover {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  transform: translateY(-2px);
}

.root .btnGhost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 26px;
  border-radius: 999px;
  background: transparent;
  border: 2px solid var(--vt-on-deep);
  color: var(--vt-on-deep);
  font-weight: 700;
  font-size: 0.95rem;
  transition: background 0.3s ease, color 0.3s ease;
}

.root .btnGhost:hover {
  background: var(--vt-on-deep);
  color: var(--vt-accent-ink);
}

.root .heroCard {
  position: absolute;
  right: 5%;
  bottom: -56px;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 300px;
  height: 300px;
  padding: 32px 26px;
  border: 12px solid var(--vt-accent);
  border-radius: 50%;
  background: var(--vt-surface-2);
  text-align: center;
}

.root .heroCardImageWrap {
  width: 92px;
  height: 92px;
  margin-bottom: 12px;
  border: 6px solid var(--vt-accent);
  border-radius: 50%;
  overflow: hidden;
}

.root .heroCardImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.root .heroCardText {
  margin: 4px 0 2px;
  color: var(--vt-ink-soft);
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.root .heroCardPhone {
  color: var(--vt-accent-ink);
  font-size: 1.15rem;
  font-weight: 800;
}

.root .section {
  padding: 96px 0;
}

.root .sectionInner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 48px;
}

.root .sectionTitle {
  margin-bottom: 16px;
  font-size: clamp(2rem, 4vw, 2.9rem);
}

.root .sectionTitle::after {
  content: '';
  display: block;
  width: 64px;
  height: 4px;
  margin-top: 10px;
  border-radius: 99px;
  background: var(--vt-accent-ink);
}

.root .lead {
  max-width: 70ch;
  margin-bottom: 40px;
  color: var(--vt-ink-soft);
  font-size: 1.12rem;
}

.root .storyGrid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 56px;
  align-items: center;
}

.root .storyText p {
  margin-bottom: 16px;
  color: var(--vt-ink-soft);
}

.root .storyText p:last-child {
  margin-bottom: 0;
}

.root .storyImageWrap {
  padding: 14px;
  background: var(--vt-accent);
  border-radius: 20px;
  transform: rotate(3deg);
  transition: transform 0.3s ease;
}

.root .storyImageWrap:hover {
  transform: rotate(0deg);
}

.root .storyImage {
  width: 100%;
  max-height: 460px;
  object-fit: cover;
  border-radius: 14px;
}

.root .servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 28px;
}

.root .serviceCard {
  position: relative;
  overflow: hidden;
  border-radius: 20px;
  background: var(--vt-surface-2);
  box-shadow: 0 10px 30px var(--vt-line);
}

.root .serviceImage {
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.root .serviceCard:hover .serviceImage {
  transform: scale(1.05);
}

.root .serviceInfo {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  padding: 28px;
}

.root .serviceInfo::before {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--vt-surface-deep);
  opacity: 0.52;
}

.root .serviceInfo > * {
  position: relative;
  z-index: 1;
}

.root .serviceTitle {
  margin-bottom: 8px;
  color: var(--vt-on-deep);
  font-size: 1.35rem;
}

.root .servicePrice {
  position: absolute;
  top: 22px;
  right: 22px;
  padding: 6px 14px;
  border-radius: 999px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  font-size: 0.78rem;
  font-weight: 800;
}

.root .serviceDesc {
  margin: 0 0 4px;
  max-width: 30ch;
  color: var(--vt-on-deep);
  opacity: 0.88;
  font-size: 0.9rem;
}

.root .serviceDuration {
  margin: 0;
  color: var(--vt-on-deep);
  opacity: 0.72;
  font-size: 0.8rem;
}

.root .priceGrid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 56px;
  align-items: start;
}

.root .priceList {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.root .priceRow {
  display: flex;
  align-items: baseline;
  gap: 16px;
}

.root .priceName {
  margin: 0;
  font-size: 1.1rem;
  white-space: nowrap;
}

.root .priceDots {
  flex: 1;
  border-bottom: 2px dotted var(--vt-line);
  transform: translateY(-4px);
}

.root .priceValue {
  color: var(--vt-accent-ink);
  font-size: 1.1rem;
  font-weight: 800;
  white-space: nowrap;
}

.root .priceImageWrap {
  padding: 14px;
  background: var(--vt-accent);
  border-radius: 20px;
  transform: rotate(3deg);
  transition: transform 0.3s ease;
}

.root .priceImageWrap:hover {
  transform: rotate(0deg) scale(1.02);
}

.root .priceImage {
  width: 100%;
  max-height: 520px;
  object-fit: cover;
  border-radius: 14px;
}

.root .contactGrid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 48px;
  align-items: center;
}

.root .contactInfo {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.root .social {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.root .hoursCard {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 240px;
  padding: 48px 40px;
  background: var(--vt-accent);
  border-radius: 24px;
  color: var(--vt-on-accent);
  transform: rotate(-2deg);
  box-shadow: 0 12px 32px var(--vt-line);
}

.root .hoursLabel {
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.root .hoursValue {
  font-size: 2rem;
  font-weight: 800;
  line-height: 1.2;
  text-align: center;
}

.root .footer {
  padding: 40px 0;
  background: var(--vt-surface-deep);
  border-top: 8px solid var(--vt-accent);
  color: var(--vt-on-deep);
}

.root .footerInner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 48px;
}

.root .areas {
  margin: 0;
  color: var(--vt-on-deep);
  opacity: 0.8;
}

.root .copyright {
  margin: 0;
  color: var(--vt-on-deep);
  opacity: 0.6;
  font-size: 0.85rem;
}

@media (max-width: 1099px) {
  .root .sidebar {
    width: 260px;
  }

  .root .main {
    margin-left: 260px;
  }

  .root .hero {
    padding: 80px 40px;
  }

  .root .heroCard {
    width: 260px;
    height: 260px;
    bottom: -48px;
    right: 3%;
  }

  .root .heroCardImageWrap {
    width: 76px;
    height: 76px;
  }
}

@media (max-width: 991px) {
  .root .sidebar {
    position: static;
    width: 100%;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    gap: 24px;
    padding: 16px 24px;
  }

  .root .logo {
    flex-shrink: 0;
  }

  .root .logoBrand {
    width: 120px;
  }

  .root .navLinks {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 14px;
  }

  .root .navLinks a {
    padding: 6px 10px;
    font-size: 0.85rem;
  }

  .root .navLinks a::after {
    display: none;
  }

  .root .main {
    margin-left: 0;
  }

  .root .hero {
    min-height: 70vh;
    padding: 80px 32px;
  }

  .root .heroCard {
    display: none;
  }

  .root .section {
    padding: 80px 0;
  }

  .root .sectionInner {
    padding: 0 32px;
  }

  .root .storyGrid,
  .root .priceGrid,
  .root .contactGrid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .root .storyImageWrap {
    max-width: 640px;
  }

  .root .priceImageWrap {
    max-width: 640px;
  }
}

@media (max-width: 640px) {
  .root .sidebar {
    flex-wrap: wrap;
    padding: 14px 18px;
    gap: 12px;
  }

  .root .logoBrand {
    width: 104px;
  }

  .root .navLinks {
    justify-content: flex-start;
    gap: 8px;
  }

  .root .hero {
    min-height: 64vh;
    padding: 72px 24px;
    align-items: flex-end;
  }

  .root .heroTitle {
    font-size: 2.2rem;
  }

  .root .heroTagline {
    font-size: 0.98rem;
  }

  .root .heroButtons {
    flex-direction: column;
    align-items: stretch;
  }

  .root .btnPrimary,
  .root .btnGhost {
    padding: 11px 20px;
    text-align: center;
  }

  .root .section {
    padding: 60px 0;
  }

  .root .sectionInner {
    padding: 0 20px;
  }

  .root .servicesGrid {
    grid-template-columns: 1fr;
    gap: 18px;
  }

  .root .serviceInfo {
    padding: 20px;
  }

  .root .serviceTitle {
    font-size: 1.15rem;
  }

  .root .servicePrice {
    top: 16px;
    right: 16px;
  }

  .root .priceGrid {
    gap: 32px;
  }

  .root .priceRow {
    gap: 10px;
  }

  .root .contactGrid {
    gap: 28px;
  }

  .root .hoursCard {
    min-height: 180px;
    padding: 32px 24px;
  }

  .root .hoursValue {
    font-size: 1.5rem;
  }

  .root .footerInner {
    padding: 0 20px;
    flex-direction: column;
    text-align: center;
  }
}
